var n=[{title:`Wat telt als progressie`,text:`Je kunt iets meer gewicht tillen voor dezelfde herhalingen, meer herhalingen doen met hetzelfde gewicht, een set toevoegen die je nog met goede vorm kunt afmaken, meer van je bewegingsbereik gebruiken of overstappen op een zwaardere variant met lichaamsgewicht. Kortere rust stopt meer werk in de training, maar kan je topkrachtprestatie verlagen, gebruik het dus alleen als het je doel dient.`},{title:`Kwaliteit die je kunt herhalen`,text:`Controleer voordat je gewicht toevoegt of de beweging beheerst is, je de geplande herhalingen afmaakt en de inspanning bij het schema past. Techniek ziet er niet op elk lichaam hetzelfde uit, maar voor jou moet het elke keer hetzelfde lijken. Doorduwen terwijl pijn erger wordt of de beweging onvast wordt, is geen productieve overload.`},{title:`Voorbeeld`,text:`Stel dat het doel twee sets van 8–12 goblet squats is. Je doet 10 en 9 herhalingen, de volgende keer 11 en 10, daarna 12 en 12. Nu is een kleine gewichtsverhoging met minder herhalingen zinvol. Heb je dumbbells met vast gewicht, dan kun je de beweging langzamer doen voor meer controle of een zwaardere variant kiezen.`},{title:`Eén verandering tegelijk`,text:`Als je sets, gewicht, frequentie en complexiteit van de oefening allemaal tegelijk verhoogt, wordt het moeilijk te zien waar je vermoeidheid vandaan komt. Verander eerst de variabele die het meest uitmaakt en geef je lichaam tijd om zich aan te passen. De vooruitgang vertraagt naarmate je meer ervaring krijgt, en sommige trainingen moeten gewoon je huidige niveau vasthouden.`},{title:`TrainUp gebruiken`,text:`De app legt de herhalingen vast die je afrondt, de inspanning van je training (RPE) en eventuele pijn die je meldt. Het gewicht kies je zelf. Als je je schema opnieuw maakt na minstens 3 trainingen, wordt het alleen een stap zwaarder als je laatste 4 trainingen licht (RPE 5 of lager) en volledig waren. Bij recente pijn volgt geen verhoging, en als 2 van je laatste 3 trainingen zeer zwaar waren (RPE 9 of hoger) of voor minder dan 60% zijn afgerond, wordt het volgende schema lichter.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: techniek bij krachttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:n,sources:i};export{a as default,n as sections,i as sources};